64	// Create runs the full scaffold: resolve release, download tarball, extract,
65	// load manifest, resolve values (with optional interactive prompting), render.
66	func Create(ctx context.Context, opts CreateOptions) error {
67		opts.applyDefaults()
68		if err := validateCreateOptions(opts); err != nil {
69			return err
70		}
71	
72		gh := newConfiguredGitHub(opts.HTTP, opts.UserAgent, opts.GitHubBaseURL)
73		tag, err := resolveReleaseTag(ctx, gh, opts.Owner, opts.Repo, opts.Version)
74		if err != nil {
75			return err
76		}
77		fmt.Fprintf(opts.Stderr, "fetching %s/%s@%s\n", opts.Owner, opts.Repo, tag)
