111	func validateCreateOptions(opts CreateOptions) error {
112		if err := validateBlueprintName(opts.Blueprint); err != nil {
113			return err
114		}
115		if opts.OutputDir == "" {
116			return errors.New("--output is required")
117		}
118		return nil
119	}
