121	func prepareCreateTemplate(blueprintRoot string, opts CreateOptions) (*Template, map[string]any, error) {
122		tmpl, err := LoadTemplate(filepath.Join(blueprintRoot, templateManifestName))
123		if err != nil {
124			return nil, nil, err
125		}
126	
127		prompter := selectPrompter(&opts)
128		values, err := Resolve(tmpl, opts.Files, opts.Stdin, opts.SetValues, prompter)
129		if err != nil {
130			return nil, nil, err
131		}
132		return tmpl, values, nil
133	}
134	
135	func renderCreateOutput(blueprintRoot, blueprintName, outputDir string, force bool, values map[string]any) error {
136		skelRoot := filepath.Join(blueprintRoot, blueprintSkeletonDir)
137		if info, err := os.Stat(skelRoot); err != nil || !info.IsDir() {
138			return fmt.Errorf("blueprint %q is missing %s/ directory", blueprintName, blueprintSkeletonDir)
139		}
140		if err := ensureOutputDir(outputDir, force); err != nil {
141			return err
142		}
143		return Render(skelRoot, outputDir, values)
144	}
145	
146	func maybeWriteCreateResult(opts CreateOptions, tmpl *Template, values map[string]any, tag string) error {
147		if opts.OutputJSON == "" {
148			return nil
149		}
150	
151		absOut, err := filepath.Abs(opts.OutputDir)
152		if err != nil {
153			absOut = opts.OutputDir
154		}
155		result := CreateResult{
156			Blueprint: tmpl.Metadata.Name,
157			Owner:     opts.Owner,
158			Repo:      opts.Repo,
159			Version:   tag,
160			OutputDir: absOut,
161			Values:    values,
162		}
163		if err := writeOutputJSON(opts.OutputJSON, opts.Stdout, result); err != nil {
164			return fmt.Errorf("write --output-json: %w", err)
165		}
166		return nil
167	}
168	
169	func writeOutputJSON(path string, stdout io.Writer, r CreateResult) error {
170		data, err := json.MarshalIndent(r, "", "  ")
171		if err != nil {
172			return err
173		}
174		data = append(data, '\n')
175		if path == "-" {
176			_, err := stdout.Write(data)
177			return err
178		}
179		return os.WriteFile(path, data, 0o644)
180	}
181	
182	// EnsureOutputDir creates dir if missing and refuses to render into a
183	// non-empty directory unless force is set.
184	func EnsureOutputDir(dir string, force bool) error {
185		return ensureOutputDir(dir, force)
186	}
187	
188	func ensureOutputDir(dir string, force bool) error {
189		info, err := os.Stat(dir)
190		switch {
191		case errors.Is(err, os.ErrNotExist):
192			return os.MkdirAll(dir, 0o755)
193		case err != nil:
194			return err
195		case !info.IsDir():
196			return fmt.Errorf("--output %s exists and is not a directory", dir)
197		}
198		entries, err := os.ReadDir(dir)
199		if err != nil {
200			return err
201		}
202		if len(entries) > 0 && !force {
203			return fmt.Errorf("--output %s is not empty (use --force to overwrite)", dir)
204		}
205		return nil
206	}
207	
208	// validateBlueprintName rejects empty names and anything that could escape the
209	// extracted tarball root via filepath.Join (separators, parent refs, hidden
210	// directories). The blueprint argument is user input that we turn directly into
211	// a path segment, so it has to be sanitized.
212	func validateBlueprintName(name string) error {
213		if name == "" {
214			return errors.New("blueprint name is required")
215		}
216		if name == "." || name == ".." || strings.HasPrefix(name, ".") {
217			return fmt.Errorf("invalid blueprint name %q", name)
218		}
219		if strings.ContainsAny(name, `/\`) {
220			return fmt.Errorf("invalid blueprint name %q (must be a single path segment)", name)
221		}
222		return nil
223	}
224	
225	func selectPrompter(opts *CreateOptions) Prompter {
226		return AutoPrompter(opts.Stdin, opts.Stderr, opts.NoInput)
227	}
